-- Explicações por artigo — Decreto do Serviço de Identificação do Cidadão. Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Este Decreto dispõe sobre o Serviço de Identificação do Cidadão, institui a Câmara-Executiva Federal de Identificação do Cidadão (Cefic) e dispõe sobre a governança da identificação das pessoas naturais no âmbito da administração pública federal direta, autárquica e fundacional.', '["Serviço de Identificação do Cidadão.","Cria a Cefic.","Governança da identificação na administração federal direta, autárquica e fundacional."]'::jsonb, '["Alcance: administração FEDERAL direta, autárquica e fundacional."]'::jsonb, 'O Decreto organiza como o governo federal identifica as pessoas.', '["Assertiva que estende a governança a empresas privadas erra: é a administração federal."]'::jsonb, '[{"termo":"Cefic","significado":"Câmara-Executiva Federal de Identificação do Cidadão."}]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'sic' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Serviço de Identificação do Cidadão é o conjunto de procedimentos e operações de gestão e verificação da identidade das pessoas naturais, por meio dos dados de identificação e dos dados cadastrais, perante a administração pública federal direta, autárquica e fundacional. Ele será utilizado para a expedição da Carteira de Identidade pelos órgãos de identificação dos Estados e do Distrito Federal.', '["Conjunto de procedimentos de gestão e verificação da identidade.","Usado para expedir a Carteira de Identidade pelos Estados e pelo DF."]'::jsonb, '["Serve também à expedição da Carteira de Identidade pelos Estados."]'::jsonb, 'O Serviço confere a identidade do requerente na expedição da carteira.', '["Assertiva que restringe o Serviço aos órgãos federais, sem relação com os Estados, erra."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'sic' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Serviço de Identificação do Cidadão é de uso facultativo para a identificação criminal e para procedimentos de identificação em sistemas relacionados à defesa nacional e à segurança do Estado, e obrigatório nas demais hipóteses, inclusive nos processos de composição de dados no modelo da Carteira de Identidade. Terá interface eletrônica com os dados da declaração de nascido vivo e da declaração de óbito, do registro civil e da Identificação Civil Nacional.', '["Facultativo: identificação criminal e defesa nacional e segurança do Estado.","Obrigatório nas demais hipóteses.","Interface com nascido vivo, óbito, registro civil e ICN."]'::jsonb, '["Facultativo: identificação criminal e defesa nacional; no mais, obrigatório."]'::jsonb, 'A polícia pode, mas não precisa, usar o Serviço na identificação criminal.', '["Assertiva que torna obrigatório o uso na identificação criminal erra: é facultativo."]'::jsonb, '[]'::jsonb, '["Lei da Identificação Criminal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'sic' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Serviço de Identificação do Cidadão não utilizará dados protegidos por sigilo legal e observará a Lei Geral de Proteção de Dados e as normas da Autoridade Nacional de Proteção de Dados (ANPD), para assegurar a privacidade e a proteção dos dados pessoais.', '["Não usa dados protegidos por sigilo legal.","Observa a LGPD e as normas da ANPD."]'::jsonb, '["Proteção de dados pessoais obrigatória."]'::jsonb, 'Dados sigilosos por lei ficam fora do Serviço.', '["Assertiva que dispensa a LGPD no Serviço erra."]'::jsonb, '[{"termo":"ANPD","significado":"Autoridade Nacional de Proteção de Dados."}]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'sic' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O número de inscrição no CPF é a chave de vinculação dos dados da pessoa natural no Serviço de Identificação do Cidadão. O Serviço abrangerá as funcionalidades de inscrever, alterar e cancelar por motivo de óbito o número de inscrição no CPF.', '["CPF como chave de vinculação dos dados.","Funcionalidades: inscrever, alterar e cancelar por óbito."]'::jsonb, '["O CPF é a CHAVE do sistema."]'::jsonb, 'Todos os dados da pessoa se ligam ao CPF.', '["Assertiva que adota o número do RG como chave erra: é o CPF."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'sic' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Serviço de Identificação do Cidadão possui as finalidades de possibilitar o acesso aos dados das bases biográficas e biométricas aprovadas pela Cefic; autenticar os dados de identificação e cadastrais da pessoa natural; e viabilizar meio unificado de identificação e atualização de dados de identificação nos cadastros administrativos.', '["Acesso às bases biográficas e biométricas aprovadas pela Cefic.","Autenticação dos dados.","Meio unificado de identificação e atualização."]'::jsonb, '["Três finalidades."]'::jsonb, 'O cadastro de um órgão atualiza o nome do cidadão a partir do Serviço.', '["Assertiva que lista apenas duas finalidades erra: são três."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'sic' and u.unit_key = 'art-6'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O compartilhamento de dados pessoais entre órgãos e entidades da administração federal direta, autárquica e fundacional no âmbito do Serviço observará orientações como: finalidades legítimas, específicas e explícitas; compatibilidade entre o tratamento e as finalidades; limitação do compartilhamento ao mínimo necessário; cumprimento integral dos requisitos da LGPD no que for compatível com o setor público; publicidade do compartilhamento no sítio da Cefic e do órgão controlador; e mecanismos de controle de acesso com auditoria e rastreamento.', '["Finalidade legítima, específica e explícita.","Compatibilidade e mínimo necessário.","Cumprimento da LGPD.","Publicidade do compartilhamento.","Controle de acesso com auditoria e rastreamento."]'::jsonb, '["Segue os princípios da LGPD: finalidade, adequação e necessidade."]'::jsonb, 'O órgão só recebe os dados necessários à sua finalidade.', '["Assertiva que autoriza o compartilhamento amplo de dados sem finalidade definida erra."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'sic' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os cadastros administrativos existentes na administração federal direta, autárquica e fundacional deverão obter obrigatoriamente do Serviço de Identificação do Cidadão os dados de identificação: nome, nome social, data de nascimento, filiação, naturalidade, nacionalidade, sexo, número do CPF, CPF da filiação, data de óbito e imagem da face do titular. Se a inscrição no CPF estiver suspensa, cancelada ou nula, ou indicar titular falecido, o Serviço informará a situação e os motivos. Os dados não listados obtidos nos cadastros serão disponibilizados ao Serviço. Não será necessário criar novos campos nos cadastros que não os tenham.', '["Onze dados de identificação obtidos obrigatoriamente do Serviço.","Informação sobre a situação cadastral do CPF.","Dados não listados são disponibilizados ao Serviço.","Sem obrigação de criar novos campos."]'::jsonb, '["Os cadastros administrativos devem obter os dados do SERVIÇO."]'::jsonb, 'O cadastro do órgão obtém do Serviço a data de óbito do titular.', '["Assertiva que obriga a criação de novos campos em todos os cadastros erra: não é necessário."]'::jsonb, '[]'::jsonb, '["Art. 27"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'sic' and u.unit_key = 'art-8'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Cefic atuará na governança da identificação da pessoa natural no âmbito da administração pública federal direta, autárquica e fundacional e da expedição da Carteira de Identidade junto aos Estados e ao Distrito Federal.', '["Governança da identificação na administração federal.","Governança da expedição da Carteira de Identidade com Estados e DF."]'::jsonb, '["Dupla frente da Cefic."]'::jsonb, 'A Cefic edita normas para a expedição da carteira nos Estados.', '["Assertiva que restringe a Cefic à administração federal erra: ela atua também junto aos Estados."]'::jsonb, '[]'::jsonb, '["Art. 10"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'sic' and u.unit_key = 'art-9'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete à Cefic editar normas sobre o aprimoramento da identificação das pessoas naturais; o uso do Serviço, observados o sigilo legal e a proteção de dados; a cooperação com o Tribunal Superior Eleitoral, em matéria de Identificação Civil Nacional, e com o Conselho Nacional de Justiça, em registro civil; os padrões técnicos das bases e dados de identificação; os padrões de documentos de segurança; a cooperação com entidades públicas e privadas; a transparência e a proteção de dados; e a Carteira de Identidade, como padrões de expedição, procedimentos de verificação, requisitos de segurança, padrões biométricos e informações de saúde.', '["Normas de identificação, uso do Serviço e proteção de dados.","Cooperação com TSE (ICN) e CNJ (registro civil).","Padrões técnicos de bases e documentos de segurança.","Normas sobre a Carteira de Identidade."]'::jsonb, '["Cefic COOPERA com TSE e CNJ conforme a matéria."]'::jsonb, 'A Cefic fixa o padrão biométrico da carteira.', '["Assertiva que exclui a Cefic da edição de normas sobre a Carteira de Identidade erra."]'::jsonb, '[]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'sic' and u.unit_key = 'art-10'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Cefic é composta por representantes da Casa Civil da Presidência da República, que a coordena; da Secretaria Especial da Receita Federal; da Secretaria de Governo Digital do Ministério da Gestão e da Inovação em Serviços Públicos; do Ministério da Justiça e Segurança Pública; e do Ministério da Saúde. Cada membro terá um suplente. Os membros e suplentes serão indicados pelos titulares dos órgãos e designados por ato do Secretário de Governo Digital, e deverão ocupar Cargo Comissionado Executivo de nível 15 ou superior. O Coordenador poderá convidar outros participantes, sem direito a voto.', '["Casa Civil coordena.","Receita Federal, Governo Digital, Justiça e Segurança Pública e Saúde.","Cada membro com suplente.","Cargo Comissionado Executivo de nível 15 ou superior.","Convidados sem voto."]'::jsonb, '["Quem coordena a Cefic é a CASA CIVIL."]'::jsonb, 'O Coordenador convida um pesquisador para uma reunião, sem direito a voto.', '["Assertiva que atribui a coordenação ao Ministério da Justiça erra: é da Casa Civil."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'sic' and u.unit_key = 'art-11'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Cefic se reunirá, em caráter ordinário, mensalmente, e, em caráter extraordinário, quando convocada por seu Coordenador. O quórum de reunião é de maioria absoluta e o de aprovação é de maioria simples. O Coordenador poderá cancelar as reuniões ordinárias quando não houver matéria a deliberar.', '["Reunião ordinária mensal.","Extraordinária por convocação do Coordenador.","Quórum de reunião: maioria absoluta; de aprovação: maioria simples.","Cancelamento sem matéria."]'::jsonb, '["Quórum de reunião ABSOLUTA; de aprovação SIMPLES."]'::jsonb, 'A reunião só começa com a maioria absoluta dos membros.', '["Assertiva que exige maioria absoluta para aprovar as matérias erra: é maioria simples."]'::jsonb, '[]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'sic' and u.unit_key = 'art-12'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

