insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os grupos técnicos da Cefic serão instituídos e compostos por ato da Cefic; terão no máximo seis membros; serão temporários, com duração não superior a um ano; e estarão limitados a, no máximo, três em operação simultânea. Poderão ser convidados representantes de outros órgãos e entidades, pesquisadores e representantes da sociedade civil.', '["No máximo seis membros.","Duração não superior a um ano.","No máximo três grupos simultâneos.","Convidados da sociedade civil."]'::jsonb, '["Limites: seis membros, um ano e três grupos."]'::jsonb, 'A Cefic não pode manter quatro grupos técnicos ao mesmo tempo.', '["Assertiva que permite grupos técnicos permanentes erra: são temporários, com até um ano."]'::jsonb, '[]'::jsonb, '["Art. 14"]'::jsonb, 'under_review', 'claude'
