insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete ao Ministério da Justiça e Segurança Pública a implementação, gestão e sustentação da base de dados de identificação e cadastrais obtidos dos órgãos de identificação dos entes federativos e da administração federal; a implementação, gestão e sustentação na confecção e leitura do QR code e dos formulários dos modelos físicos da carteira; e a coordenação, por meio da Secretaria Nacional de Segurança Pública, com auxílio da Cefic, da aquisição dos objetos necessários junto aos entes federativos, com recursos do Fundo Nacional de Segurança Pública ou de outras fontes. A tecnologia do QR code poderá ser usada por outras entidades.', '["Base de dados de identificação e cadastrais.","QR code e formulários físicos.","Aquisição de objetos junto aos entes com recursos do Fundo Nacional de Segurança Pública."]'::jsonb, '["Aquisição coordenada pela Secretaria Nacional de Segurança Pública."]'::jsonb, 'O Ministério da Justiça coordena a compra de insumos da carteira com recursos do Fundo Nacional de Segurança Pública.', '["Assertiva que atribui ao Ministério da Gestão a base de dados de identificação erra: é do Ministério da Justiça."]'::jsonb, '[]'::jsonb, '["Art. 19"]'::jsonb, 'under_review', 'claude'
